/**
 * Next per-project issue number. Archived issues keep their number, so the
290→ * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
300→      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
