/**
 * Active members of this workspace, keyed by lower-cased email.
 * Removed, invited and suspended members are absent, so a caller can treat
 * a missing address as "leave unassigned" without a second lookup.
 */
export async function listActiveMemberIdsByEmail(
  orgId: OrgId,
): Promise<ReadonlyMap<string, UserId>> {
  const rows = getDb()
    .select({ email: users.email, userId: members.userId })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  const byEmail = new Map<string, UserId>();
  for (const row of rows) {
    byEmail.set(row.email.toLowerCase(), brandId<UserId>(row.userId));
  }
  return byEmail;
}

