/** Colour applied when an import creates a label that does not exist yet. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export type IssueImportRecord = {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
};

export type ImportedIssueWrite = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Already de-duplicated, in first-seen order. */
  readonly labelNames: readonly string[];
};

/** The previous import for this workspace key, or null when the key is fresh. */
export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<string>(row.issueIds).map((id) =>
      brandId<IssueId>(id),
    ),
  };
}

/** Loads issues in the given id order, including archived rows. */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.id, [...issueIds]),
      ),
    )
    .all();

  const labelMap = await listLabelsForIssues(orgId, issueIds);
  const byId = new Map(
    rows.map((row) => [
      row.id,
      toIssue(row, (labelMap[row.id] ?? []).map((label) => label.id)),
    ]),
  );

  return issueIds.flatMap((id) => {
    const issue = byId.get(id);
    return issue ? [issue] : [];
  });
}

/**
 * Creates every missing label, the issue rows and the import record in one
 * transaction. Numbers continue after the highest number the project has
 * ever used. A failure rolls the whole batch back, including the key.
 */
export async function insertImportedIssues(input: {
  orgId: OrgId;
  projectId: ProjectId;
  importKey: string;
  authorId: UserId;
  rows: readonly ImportedIssueWrite[];
}): Promise<readonly Issue[]> {
  const db = getDb();

  return db.transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());
    const existingLabels = tx
      .select()
      .from(labels)
      .where(orgPredicate(labels.orgId, input.orgId))
      .all();

    const labelIdByName = new Map<string, LabelId>(
      existingLabels.map((label) => [label.name, brandId<LabelId>(label.id)]),
    );

    const neededNames: string[] = [];
    const seenNames = new Set<string>();
    for (const row of input.rows) {
      for (const name of row.labelNames) {
        if (seenNames.has(name)) continue;
        seenNames.add(name);
        neededNames.push(name);
      }
    }

    for (const name of neededNames) {
      if (labelIdByName.has(name)) continue;
      const id = newId();
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, brandId<LabelId>(id));
    }

    const maxRow = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = (maxRow?.value ?? 0) + 1;

    const created: Issue[] = [];
    const issueIds: string[] = [];

    for (const row of input.rows) {
      const id = newId();
      const labelIds = row.labelNames.map((name) => {
        const labelId = labelIdByName.get(name);
        if (!labelId) throw new Error(`Label "${name}" was not created`);
        return labelId;
      });

      const inserted = tx
        .insert(issues)
        .values({
          id,
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
