/**
 * Turns every row into an issue, in file order.
 *
 * Access matches `createIssue`. Quota and the `issue:create` rate allowance
 * are charged for the whole batch before anything is written; a refusal
 * persists nothing, so the same key can be uploaded again. A key this
 * workspace has already imported returns that first result and publishes
 * nothing.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const existing = await issueRepo.findIssueImport(input.orgId, input.importKey);
  if (existing) {
    return {
      importKey: input.importKey,
      projectId: existing.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, existing.issueIds),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const membersByEmail = await memberRepo.listActiveMemberIdsByEmail(input.orgId);
  const rows = input.rows.map((row) => ({
    title: row.title,
    description: row.description,
    status: row.status,
    priority: row.priority,
    assigneeId:
      row.assigneeEmail === null
        ? null
        : (membersByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
    dueAt: row.dueAt,
    labelNames: uniqueInOrder(row.labels),
  }));

  let issues: readonly Issue[];
  try {
    issues = await issueRepo.insertImportedIssues({
      orgId: input.orgId,
      projectId: input.projectId,
      importKey: input.importKey,
      authorId: actor.userId,
      rows,
    });
  } catch (error) {
    if (!isIssueImportConflict(error)) throw error;
    const raced = await issueRepo.findIssueImport(input.orgId, input.importKey);
    if (!raced) throw error;
    return {
      importKey: input.importKey,
      projectId: raced.projectId,
      issues: await issueRepo.findIssuesByIds(input.orgId, raced.issueIds),
      replayed: true,
    };
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues,
    replayed: false,
  };
}

function uniqueInOrder(names: readonly string[]): readonly string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const name of names) {
    if (seen.has(name)) continue;
    seen.add(name);
    unique.push(name);
  }
  return unique;
}

function isIssueImportConflict(error: unknown): boolean {
  return (
    error instanceof Error &&
    error.message.includes("UNIQUE") &&
    error.message.includes("issue_imports")
  );
}

