  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

function rows(
  titles: readonly string[],
  extra: Record<string, unknown> = {},
) {
  return titles.map((title) => ({ title, ...extra }));
}

describe("importIssues", () => {
  it("parses defaults and rejects an empty batch", () => {
    const parsed = importIssuesSchema.parse({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "upload-key-1",
      rows: [{ title: "First row" }],
    });
    expect(parsed.rows[0]).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      assigneeEmail: null,
      labels: [],
      dueAt: null,
    });
    expect(
      importIssuesSchema.safeParse({
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "short",
        rows: [],
      }).success,
    ).toBe(false);
  });

  it("refuses a viewer, a foreign org, an unknown project and an archived project", async () => {
    const input = importIssuesSchema.parse({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "refused-viewer1",
      rows: [{ title: "Nope from viewer" }],
    });

    await expect(
      issueService.importIssues(tenant.actors.viewer, input),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.importIssues(other.actors.member, input),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        importIssuesSchema.parse({
          ...input,
          importKey: "missing-project",
          projectId: other.project.id,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Old",
      slug: "old",
      key: "OLD",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#000000",
      targetDate: null,
    });
    await projectRepo.archiveProject(tenant.org.id, archived.id);
    await expect(
      issueService.importIssues(
        tenant.actors.member,
        importIssuesSchema.parse({
          orgId: tenant.org.id,
          projectId: archived.id,
          importKey: "archived-project",
          rows: [{ title: "Should not land" }],
        }),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const stored = getDb()
      .select()
      .from(issueImports)
      .where(eq(issueImports.orgId, tenant.org.id))
      .all();
    expect(stored).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(0);
  });

  it("imports rows in order and replays without creating more", async () => {
    const seenCreated: unknown[] = [];
    const seenImported: unknown[] = [];
    const offCreated = subscribe("issue.created", (payload) => {
      seenCreated.push(payload);
    });
    const offImported = subscribe("issues.imported", (payload) => {
      seenImported.push(payload);
    });

    const due = "2026-05-01T12:00:00.000Z";
    const input = importIssuesSchema.parse({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      importKey: "batch-alpha-1",
      rows: [
        {
          title: "First imported",
          description: "details",
          status: "in_progress",
          priority: "high",
          assigneeEmail: "MEMBER@import.test",
          labels: ["Bug", "Bug", "backend"],
          dueAt: due,
        },
        {
          title: "Second imported",
          assigneeEmail: "nobody@example.com",
          labels: ["backend", "bug"],
        },
      ],
    });

    const first = await issueService.importIssues(tenant.actors.member, input);
    expect(first.replayed).toBe(false);
    expect(first.projectId).toBe(tenant.project.id);
    expect(first.issues.map((issue) => issue.title)).toEqual([
      "First imported",
      "Second imported",
    ]);
    expect(first.issues.map((issue) => issue.number)).toEqual([1, 2]);
    expect(first.issues[0]).toMatchObject({
      description: "details",
      status: "in_progress",
      priority: "high",
      authorId: tenant.actors.member.userId,
      assigneeId: tenant.userIds.member,
      parentId: null,
      estimate: null,
      dueAt: due,
      startedAt: null,
      completedAt: null,
    });
    expect(first.issues[1]?.assigneeId).toBeNull();

    const orgLabels = await labelRepo.listLabels(tenant.org.id);
    const bug = orgLabels.find((label) => label.name === "Bug");
    const backend = orgLabels.find((label) => label.name === "backend");
    const lower = orgLabels.find((label) => label.name === "bug");
    expect(bug).toMatchObject({ color: "#94a3b8", description: null });
    expect(backend).toMatchObject({ color: "#94a3b8", description: null });
    expect(lower).toMatchObject({ color: "#94a3b8", description: null });
    expect(orgLabels.filter((label) => label.name === "backend")).toHaveLength(1);
    expect(first.issues[0]?.labelIds).toEqual([bug?.id, backend?.id]);
    expect(first.issues[1]?.labelIds).toEqual([backend?.id, lower?.id]);

    const again = await issueService.importIssues(tenant.actors.member, {
      ...input,
      rows: [{ title: "Completely different", labels: ["nope"] }],
    });
    expect(again.replayed).toBe(true);
    expect(again.issues.map((issue) => issue.id)).toEqual(
      first.issues.map((issue) => issue.id),
    );
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(2);
    expect((await labelRepo.listLabels(tenant.org.id)).some((l) => l.name === "nope")).toBe(
      false,
    );

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "After the import" }),
    );
    expect(created.number).toBe(3);

    expect(seenCreated).toHaveLength(1);
    expect(seenImported).toHaveLength(1);
    expect(seenImported[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.actors.member.userId,
      projectId: tenant.project.id,
      importKey: "batch-alpha-1",
      issueIds: first.issues.map((issue) => issue.id),
    });

    offCreated();
    offImported();

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 25,
      cursor: null,
    });
    expect(activity.items).toHaveLength(1);
    expect(activity.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.actors.member.userId,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "batch-alpha-1" },
    });
    const perIssue = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 25,
      cursor: null,
    });
    expect(perIssue.items).toHaveLength(1);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.issuesUsed).toBe(3);
    expect(recounted.issuesUsed).toBe(3);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "First imported",
      limit: 10,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.subjectId)).toContain(first.issues[0]?.id);

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      limit: 25,
      cursor: null,
    });
    expect(notes.items).toHaveLength(0);

    const deliveries = getDb().select().from(webhookDeliveries).all();
    expect(deliveries).toHaveLength(0);
  });

  it("does not keep a key when quota or the rate allowance refuses the batch", async () => {
    const quotaTenant = await createTenant("import-quota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: `Seed ${number}`,
        }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        quotaTenant.actors.member,
        importIssuesSchema.parse({
          orgId: quotaTenant.org.id,
          projectId: quotaTenant.project.id,
          importKey: "over-quota-key",
          rows: rows(["One more", "And another"]),
        }),
      ),
    ).rejects.toThrow(/allows no more issues/);
    expect(
      await issueRepo.findIssueImport(quotaTenant.org.id, "over-quota-key"),
    ).toBeNull();
    expect(await issueRepo.countIssues(quotaTenant.org.id, quotaTenant.project.id)).toBe(99);

    const one = await issueService.importIssues(
      quotaTenant.actors.member,
      importIssuesSchema.parse({
        orgId: quotaTenant.org.id,
        projectId: quotaTenant.project.id,
        importKey: "fits-quota-key",
        rows: [{ title: "The last slot" }],
      }),
    );
    expect(one.issues[0]?.number).toBe(100);

    resetRateLimits();
    const rateTenant = await createTenant("import-rate", "free");
    const many = Array.from({ length: 61 }, (_, index) => ({
      title: `Rate row ${index + 1}`,
    }));
    await expect(
      issueService.importIssues(
        rateTenant.actors.member,
        importIssuesSchema.parse({
          orgId: rateTenant.org.id,
          projectId: rateTenant.project.id,
          importKey: "too-fast-key",
          rows: many,
        }),
      ),
    ).rejects.toThrow(/rate limit/i);
    expect(await issueRepo.countIssues(rateTenant.org.id, rateTenant.project.id)).toBe(0);
    expect(await issueRepo.findIssueImport(rateTenant.org.id, "too-fast-key")).toBeNull();

    resetRateLimits();
    const later = await issueService.importIssues(
      rateTenant.actors.member,
      importIssuesSchema.parse({
        orgId: rateTenant.org.id,
        projectId: rateTenant.project.id,
        importKey: "too-fast-key",
        rows: [{ title: "Now it fits" }],
      }),
    );
    expect(later.replayed).toBe(false);
    expect(later.issues).toHaveLength(1);
  });

  it("leaves removed members and other workspaces unassigned, and ignores their labels", async () => {
    const removed = await userRepo.insertUser({
      email: "gone@import.test",
      name: "Gone",
      passwordHash: "x",
    });
    const member = await memberRepo.insertMember(
      tenant.org.id,
      removed.id,
      "member",
      null,
    );
    await memberRepo.archiveMember(tenant.org.id, member.id);

    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "foreign",
      color: "#ff00aa",
      description: "elsewhere",
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      importIssuesSchema.parse({
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: "assignee-edges",
        rows: [
          {
            title: "Removed person",
            assigneeEmail: "gone@import.test",
            labels: ["foreign"],
          },
          {
            title: "Other workspace",
            assigneeEmail: `member@import-other.test`,
          },
        ],
      }),
    );

    expect(result.issues[0]?.assigneeId).toBeNull();
    expect(result.issues[1]?.assigneeId).toBeNull();
    const created = (await labelRepo.listLabels(tenant.org.id)).find(
      (label) => label.name === "foreign",
    );
    expect(created?.color).toBe("#94a3b8");
    expect(created?.id).not.toBe(
      (await labelRepo.listLabels(other.org.id)).find((label) => label.name === "foreign")
        ?.id,
    );
  });

  it("treats the same key in another workspace as a new import", async () => {
    const key = "shared-key-99";
    const a = await issueService.importIssues(
      tenant.actors.owner,
      importIssuesSchema.parse({
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        importKey: key,
        rows: [{ title: "Workspace A row" }],
      }),
    );
    const b = await issueService.importIssues(
      other.actors.owner,
      importIssuesSchema.parse({
        orgId: other.org.id,
        projectId: other.project.id,
        importKey: key,
        rows: [{ title: "Workspace B row" }],
      }),
    );
    expect(b.replayed).toBe(false);
    expect(b.issues[0]?.id).not.toBe(a.issues[0]?.id);
    expect(b.issues[0]?.title).toBe("Workspace B row");
  });

  it("persists the import so a fresh connection can replay it", async () => {
    const row = getDb()
      .select()
      .from(issueImports)
      .where(eq(issueImports.importKey, "batch-alpha-1"))
      .get();
    expect(row?.orgId).toBe(tenant.org.id);
    expect(JSON.parse(row?.issueIds ?? "[]")).toHaveLength(2);

    const labelsInOrg = getDb().select().from(labels).all();
    expect(labelsInOrg.length).toBeGreaterThan(0);
    expect(webhookEndpoints).toBeTruthy();
  });
});
